module rc_lpf2_rnm(input real in_val, output real out_val);

  localparam real WP_0 = 24023019.55;
  localparam real WZ_0 = 0.0;
  localparam bit HAS_ZERO_0 = 0;
  localparam real WP_1 = 164656225.6;
  localparam real WZ_1 = 0.0;
  localparam bit HAS_ZERO_1 = 0;
  localparam real OVERALL_MULT = 3.955539728e+15;
  localparam real TSTEP = 303663.0; // femtoseconds, for #(...) only
  localparam real DT_SECONDS = 3.036629791e-10; // same interval, in real seconds, for RK4 math
  localparam real DC_BIAS = 0.9;
