                                            // path so it isn't double-counted
                                            // against static_curve's own DC gain

  function automatic real static_curve(input real xin);
    real xc;
    begin
      xc = (xin < 0.0) ? 0.0 : ((xin > 1.8) ? 1.8 : xin);
      static_curve = -2.198363923e-16 + xc*(1.0);
