  real u_dev;
  real static_out;
  real dynamic_out;

  initial begin
    x_0 = 0.0;
    x_1 = 0.0;
  end

  always #(TSTEP) begin : rk4_step
    real dt;
    dt = DT_SECONDS;

    u_dev = in_val - DC_BIAS;

    // k1
        sec_in1_0 = u_dev;
        sec_out1_0 = HAS_ZERO_0 ? ((WZ_0-WP_0)*(x_0) + sec_in1_0) : (x_0);
        k1_0 = -WP_0*(x_0) + sec_in1_0;
        sec_in1_1 = sec_out1_0;
        sec_out1_1 = HAS_ZERO_1 ? ((WZ_1-WP_1)*(x_1) + sec_in1_1) : (x_1);
        k1_1 = -WP_1*(x_1) + sec_in1_1;

    // k2
