        k2_1 = -WP_1*(x_1 + 0.5*dt*k1_1) + sec_in2_1;

    // k3
        sec_in3_0 = u_dev;
        sec_out3_0 = HAS_ZERO_0 ? ((WZ_0-WP_0)*(x_0 + 0.5*dt*k2_0) + sec_in3_0) : (x_0 + 0.5*dt*k2_0);
        k3_0 = -WP_0*(x_0 + 0.5*dt*k2_0) + sec_in3_0;
        sec_in3_1 = sec_out3_0;
        sec_out3_1 = HAS_ZERO_1 ? ((WZ_1-WP_1)*(x_1 + 0.5*dt*k2_1) + sec_in3_1) : (x_1 + 0.5*dt*k2_1);
        k3_1 = -WP_1*(x_1 + 0.5*dt*k2_1) + sec_in3_1;

    // k4
        sec_in4_0 = u_dev;
        sec_out4_0 = HAS_ZERO_0 ? ((WZ_0-WP_0)*(x_0 + dt*k3_0) + sec_in4_0) : (x_0 + dt*k3_0);
        k4_0 = -WP_0*(x_0 + dt*k3_0) + sec_in4_0;
        sec_in4_1 = sec_out4_0;
        sec_out4_1 = HAS_ZERO_1 ? ((WZ_1-WP_1)*(x_1 + dt*k3_1) + sec_in4_1) : (x_1 + dt*k3_1);
        k4_1 = -WP_1*(x_1 + dt*k3_1) + sec_in4_1;

    // combine and advance state
    x_0 = x_0 + (dt/6.0)*(k1_0 + 2.0*k2_0 + 2.0*k3_0 + k4_0);
    x_1 = x_1 + (dt/6.0)*(k1_1 + 2.0*k2_1 + 2.0*k3_1 + k4_1);
    dynamic_out = OVERALL_MULT * (sec_out1_1);
    static_out = static_curve(in_val);
    final_out = static_out + (dynamic_out - GAIN_DC*u_dev);
    out_val = final_out;
